{"file_path":"src/policies.js","content":"/**
 * Token bucket and sliding window policies. Each keeps one state per key
 * and exposes advance/allows/record so the simulator can drive them
 * uniformly regardless of type.
 */

export class Bucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity // BigInt
    this.refill = refill // BigInt
    this.per = per // BigInt
    // key -> { tokensNum: BigInt (tokens * per), lastTick: BigInt }
    this.states = new Map()
  }

  // tokensNum represents tokens * per as an exact integer so that partial
  // periods never need rounding.
  #capNum() {
    return this.capacity * this.per
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { tokensNum: this.#capNum(), lastTick: tick }
      this.states.set(key, state)
      return
    }
    const delta = tick - state.lastTick
    if (delta > 0n) {
      const capNum = this.#capNum()
      let next = state.tokensNum + this.refill * delta
      if (next > capNum) next = capNum
      state.tokensNum = next
      state.lastTick = tick
    }
  }

  allows(key) {
    const state = this.states.get(key)
    return state.tokensNum >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.tokensNum -= this.per
  }
}

export class Window {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit // BigInt
    this.span = span // BigInt
    // key -> array of BigInt ticks remembered, oldest first
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = []
      this.states.set(key, state)
    }
    const cutoff = tick - this.span
    let i = 0
    while (i < state.length && state[i] <= cutoff) i++
    if (i > 0) state.splice(0, i)
  }

  allows(key) {
    const state = this.states.get(key)
    return BigInt(state.length) < this.limit
  }

  record(key, tick) {
    const state = this.states.get(key)
    state.push(tick)
  }
}
"}

