 * policies, routes and an ordered event list. Throws LineError on any
 * malformed input, at the first problem encountered.
 */

import { fail } from './errors.js'
import { isValidToken, parseUint } from './grammar.js'
import { Bucket, Window } from './policies.js'

const FIELD_MIN = { capacity: 1n, refill: 0n, per: 1n, limit: 0n, span: 1n, tick: 0n }

function parseField(str, field, lineNo) {
  const v = parseUint(str)
  const min = FIELD_MIN[field]
  if (v === null || v < min) {
    fail(lineNo, `${field} must be an integer of at least ${min}`)
  }
  return v
}

export function parseLimiterFile(text) {
  let lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines = lines.slice(0, -1)
  }

  const policies = new Map() // name -> Bucket | Window
  const routes = [] // { prefix, policies: [name,...] }
  const routeByPrefix = new Map()
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const parts = trimmed.split(/\s+/)
    const directive = parts[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (seenEvent) {
        fail(lineNo, 'declarations must come before the first event')
      }
    }

    if (directive === 'bucket') {
      if (parts.length !== 5) {
        fail(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const [, name, capacityS, refillS, perS] = parts
      if (!isValidToken(name)) fail(lineNo, `invalid policy name ${name}`)
      const capacity = parseField(capacityS, 'capacity', lineNo)
      const refill = parseField(refillS, 'refill', lineNo)
      const per = parseField(perS, 'per', lineNo)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new Bucket(name, capacity, refill, per))
    } else if (directive === 'window') {
      if (parts.length !== 4) {
        fail(lineNo, 'expected window <name> <limit> <span>')
      }
      const [, name, limitS, spanS] = parts
      if (!isValidToken(name)) fail(lineNo, `invalid policy name ${name}`)
      const limit = parseField(limitS, 'limit', lineNo)
      const span = parseField(spanS, 'span', lineNo)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new Window(name, limit, span))
    } else if (directive === 'route') {
      if (parts.length < 3) {
        fail(lineNo, 'expected route <prefix> <policy>...')
      }
      const prefix = parts[1]
      const policyNames = parts.slice(2)
      if (!isValidToken(prefix)) fail(lineNo, `invalid route prefix ${prefix}`)
      if (routeByPrefix.has(prefix)) fail(lineNo, `prefix ${prefix} is routed twice`)
      for (const pname of policyNames) {
        if (!policies.has(pname)) fail(lineNo, `unknown policy ${pname}`)
      }
      const route = { prefix, policies: policyNames }
      routeByPrefix.set(prefix, route)
      routes.push(route)
    } else if (directive === 'event') {
      if (parts.length !== 3) {
        fail(lineNo, 'expected event <tick> <key>')
      }
      const [, tickS, key] = parts
      const tick = parseField(tickS, 'tick', lineNo)
      if (!isValidToken(key)) fail(lineNo, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        fail(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      seenEvent = true
      events.push({ tick, key })
    } else {
      fail(lineNo, `unknown directive ${directive}`)
    }
  }

  return { policies, routes, events }
}
