/**
 * The command. `node src/cli.js replay` verdicts every event of the
 * limiter file read from standard input, and `node src/cli.js summary`
 * totals the verdicts per key.
 */

import { LineError } from './errors.js'
import { parseLimiterFile } from './parser.js'
import { simulate } from './simulate.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (c) => chunks.push(c))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function writeAndExit(stream, text, code) {
  stream.write(text, () => {
    process.exitCode = code
  })
}

async function main() {
  const argv = process.argv.slice(2)
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'replay' && mode !== 'summary')) {
    writeAndExit(process.stderr, 'error: usage: cli.js replay|summary\n', 2)
    return
  }

  const text = await readStdin()

  let parsed
  try {
    parsed = parseLimiterFile(text)
  } catch (err) {
    if (err instanceof LineError) {
      writeAndExit(process.stderr, `error: line ${err.line}: ${err.message}\n`, 2)
      return
    }
    throw err
  }

  const { log, perKey, totalAllowed, totalDenied } = simulate(parsed)

  let out
  if (mode === 'replay') {
    const lines = log.map((e) =>
      e.allow ? `${e.tick} ${e.key} allow` : `${e.tick} ${e.key} deny ${e.denyPolicy}`
    )
    out = lines.map((l) => l + '\n').join('')
  } else {
    const keys = Array.from(perKey.keys()).sort()
    const lines = keys.map((k) => {
      const s = perKey.get(k)
      return `${k} allowed=${s.allowed} denied=${s.denied}`
    })
    lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
    out = lines.map((l) => l + '\n').join('')
  }

  writeAndExit(process.stdout, out, 0)
}

main().catch((err) => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exitCode = 2
})
"}

